                {
                  "code": "IN",
                  "name": "India"
                }
              ],
              "verificationMethod": "REAL_TIME_API",
              "requiredInputFields": [
                {
                  "fieldName": "licenceNumber",
                  "displayName": "Driving Licence Number",
                  "fieldType": "STRING",
                  "isRequired": true,
                  "validationPattern": "^[A-Z]{2}[0-9]{2}[0-9]{4}[0-9]{7}$"
